(() => {
  'use strict';
  const path = location.pathname.replace(/\/+$/, '') || '/';

  if (!document.querySelector('link[href="/assets/css/site-consistency.css"]')) {
    const consistency = document.createElement('link');
    consistency.rel = 'stylesheet';
    consistency.href = '/assets/css/site-consistency.css';
    document.head.append(consistency);
  }

  const hero = document.querySelector('.page-hero');
  if (hero && !hero.classList.contains('hero-image-selected')) {
    const heroMap = {
      '/about':'about-us-consultation',
      '/shop':'shop-product-showcase',
      '/installation':'installation-service',
      '/installations':'installation-service',
      '/maintenance':'hero-02-craftsmanship',
      '/gallery':'hero-06-evening-gathering',
      '/fireplaces':'hero-04-product-showcase',
      '/pizza-ovens':'hero-03-city-view-terrace',
      '/commercial-ovens':'about-us-workshop',
      '/residential-pizza-ovens':'hero-01-social-dining',
      '/outdoor-models':'hero-03-city-view-terrace',
      '/diy-ovens':'installation-service',
      '/mobile-compact-ovens':'hero-04-product-showcase',
      '/accessories':'shop-product-showcase',
      '/contact':'about-us-consultation',
      '/privacy-policy':'privacy-policy',
      '/account':'privacy-policy',
      '/terms':'terms-of-service',
      '/advice':'terms-of-service',
      '/compare':'shop-product-showcase',
      '/cart':'shop-product-showcase',
      '/checkout':'shop-product-showcase',
      '/showroom':'hero-04-product-showcase',
      '/stoneskin':'hero-02-craftsmanship',
      '/thank-you':'hero-06-evening-gathering'
    };
    const base = heroMap[path] || 'hero-03-city-view-terrace';
    hero.classList.add('hero-image-selected');
    hero.style.setProperty('--hero-desktop', `url('/assets/images/hero-selected/${base}-1920.webp')`);
    hero.style.setProperty('--hero-tablet', `url('/assets/images/hero-selected/${base}-1440.webp')`);
    hero.style.setProperty('--hero-mobile', `url('/assets/images/hero-selected/${base}-960.webp')`);
    hero.style.setProperty('--hero-position', 'center center');
    hero.style.setProperty('--hero-position-mobile', '58% center');
  }

  if (path.replace(/\.(?:html|php)$/i, '') === '/product') {
    const productParams = new URLSearchParams(location.search);
    const requestedName = (productParams.get('name') || '').toLowerCase();
    const requestedSlug = (productParams.get('slug') || '').toLowerCase();
    const hasExplicitProduct = productParams.has('name') || productParams.has('slug');
    const pageProductName = (document.querySelector('.product-detail h1')?.textContent || '').toLowerCase();
    const isNeapolitan = requestedName.includes('neapolitan') || requestedSlug.includes('neapolitan') || (!hasExplicitProduct && pageProductName.includes('neapolitan'));

    if (isNeapolitan) {
      const neapolitanHeroImage = 'data:image/webp;base64,' + [
        '',
        '',
        ''
      ].join('');

      const applyNeapolitanHero = () => {
        const productHero = document.querySelector('.product-page-hero');
        if (!productHero) return false;
        productHero.style.setProperty('background-image', "url('/assets/images/hero-selected/shop-product-showcase-1920.webp')", 'important');
        productHero.style.setProperty('background-size', 'cover', 'important');
        productHero.style.setProperty('background-position', 'center center', 'important');
        productHero.style.setProperty('background-repeat', 'no-repeat', 'important');
        productHero.dataset.customProductHero = 'shop-product-showcase';
        return true;
      };

      const applyHeroAfterProductScripts = () => {
        applyNeapolitanHero();
        setTimeout(applyNeapolitanHero, 120);
        setTimeout(applyNeapolitanHero, 500);
      };

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', applyHeroAfterProductScripts, {once:true});
      } else {
        applyHeroAfterProductScripts();
      }
      window.addEventListener('load', applyHeroAfterProductScripts, {once:true});
      const productMain = document.querySelector('main') || document.body;
      if (productMain) {
        const observer = new MutationObserver(() => applyNeapolitanHero());
        observer.observe(productMain, {childList:true, subtree:true});
        setTimeout(() => observer.disconnect(), 3000);
      }
    }
  }

  if (path === '/installation') {
    [...document.querySelectorAll('main section')].forEach(section => {
      const eyebrow = section.querySelector('.section-head .eyebrow');
      if (eyebrow && eyebrow.textContent.trim().toLowerCase() === 'recommended stand sizes') {
        section.remove();
      }
    });
  }

  const footer = document.querySelector('footer.footer');
  if (footer) {
    const socialAccounts = [
      ['Facebook', 'https://www.facebook.com/www.fireanddine.co.za', 'fab fa-facebook-f'],
      ['Instagram', 'https://www.instagram.com/fireanddinepizzaovens', 'fab fa-instagram'],
      ['YouTube', 'https://www.youtube.com/@FireandDine', 'fab fa-youtube']
    ];

    let socials = footer.querySelector('.socials');
    if (!socials) {
      const socialColumn = [...footer.querySelectorAll('.footer-col')].find(column => {
        const heading = column.querySelector('h3');
        return heading && /^(connect|stay connected)$/i.test(heading.textContent.trim());
      });
      if (socialColumn) {
        socials = document.createElement('div');
        socials.className = 'socials';
        socialColumn.append(socials);
      }
    }

    if (socials) {
      socials.innerHTML = socialAccounts.map(([label, url, icon]) =>
        `<a aria-label="Fire & Dine on ${label}" href="${url}" target="_blank" rel="noopener noreferrer"><i class="${icon}" aria-hidden="true"></i></a>`
      ).join('');
    }
  }

  const locations = [];
  if (path === '/') locations.push(['home', document.querySelector('.site-final-cta')]);
  if (['/installation','/maintenance','/advice'].includes(path)) locations.push(['services', document.querySelector('.site-final-cta')]);
  locations.push(['footer', document.querySelector('footer.footer')]);
  locations.forEach(async ([locationName, anchor]) => {
    if (!anchor) return;
    try {
      const html = await fetch(`/api/brochure.php?location=${locationName}`, {credentials:'same-origin'}).then(r => r.ok ? r.text() : '');
      if (!html.trim()) return;
      const template = document.createElement('template'); template.innerHTML = html.trim();
      anchor.before(template.content);
    } catch {}
  });
})();
